// EFI builder: hardware report loader/validator, macOS compatibility checker
// and OpenCore config planner.
//
// Rules and datasets are ported from lzhoang2801/OpCore-Simplify
// (BSD-3-Clause, Copyright (c) 2024 lzhoang2801). Datasets live in
// efidata.json, regenerated by scripts/gen_efi_data.py.
#ifndef EFIBUILDER_H
#define EFIBUILDER_H

#include <QJsonObject>
#include <QString>
#include <QStringList>
#include <QVariantMap>

namespace EfiBuilder {

// Darwin version range a device supports. Empty strings = unsupported.
struct Range {
  QString maxV, minV;
  bool supported() const { return !maxV.isEmpty() || !minV.isEmpty(); }
};

struct DeviceVerdict {
  QString kind;  // CPU, GPU, Sound, Network, ...
  QString name;
  Range range;
  QString note;
};

struct Compatibility {
  QList<DeviceVerdict> devices;
  QString nativeMax, nativeMin;  // intersection over required devices
  bool cpuSupported = true;
  QStringList warnings;
};

struct Plan {
  QString templateName;        // Database/BaseConfigs/<name>.plist
  QString smbios;              // PlatformInfo.Generic.SystemProductName
  QStringList kexts;           // kexts the hardware needs (bundle names)
  QString bootArgsAdd;         // appended to the template's boot-args
  QStringList notes;           // things the user must still do by hand
  int audioLayout = 0;         // AppleALC layout id (0 = none)
  QString audioPciPath;        // audio controller PCI path ("" = fall back to alcid=)
  bool audioForced = false;    // user picked a layout: wins over a layout-id already in the template
  bool secureBootOff = false;  // OCLP root patches need Misc > Security > SecureBootModel = Disabled
  QStringList acpi;            // SSDT-*.aml files to enable (from the ACPI folder analysis)
  QStringList acpiManaged;     // SSDTs the planner decided on (others are left to the base config)
};

// ---- post-install guide (https://dortania.github.io/OpenCore-Post-Install/) ----
struct NextStep {
  QString title, text, url;
};
QString postInstallGuideUrl();
// Checklist for the finished build; steps are filtered by the report and the final plan.
QList<NextStep> nextSteps(const QJsonObject& report, const Plan& plan);

// Optional "finalize for daily use" edits. All off by default.
struct Finalize {
  bool quietBoot = false;    // drop -v / debug boot-args, stop debug logging
  bool hidePicker = false;   // hide the boot picker (Esc/Space still shows it)
  bool openCanopy = false;   // graphical picker (OpenCanopy)
  bool any() const { return quietBoot || hidePicker || openCanopy; }
};
// `drivers` = .efi names in the Database; `resourcesOk` = Database has OC Resources.
void finalizeConfig(QVariantMap* config, const Finalize& f, const QStringList& drivers,
                    bool resourcesOk, QStringList* notes);

// ---- audio codec layout (OpCore Simplify "Choosing Codec Layout ID") ----
struct CodecLayout {
  int id = 0;
  QString comment;
  bool recommended = false;    // Mirone / InsanelyDeepak / Toleda / DalianSky
};
struct AudioInfo {
  QString codecId, codecName;  // e.g. "10EC-0897"
  QString controllerPciPath;   // from System Devices; empty if not found
  QList<CodecLayout> layouts;
  int defaultId = 0;
};
// Empty layouts = no supported codec in the report.
AudioInfo audioInfo(const QJsonObject& report);
void overrideAudio(Plan* p, int layoutId);

// ---- ACPI folder (tables dumped by Hardware Sniffer next to Report.json) ----
struct AcpiInfo {
  QString dir;
  bool found = false;          // folder exists
  bool hasDsdt = false;
  QStringList tables;          // *.aml file names
  QStringList warnings;
  QByteArray blob;             // concatenated DSDT + SSDT bytes, searched for names/IDs
  bool has(const char* token) const { return blob.contains(token); }
  bool hasBytes(const QByteArray& b) const { return blob.contains(b); }
  bool hasEc() const;          // an embedded controller (PNP0C09) is declared
};
AcpiInfo readAcpiFolder(const QString& dir);
// Picks SSDTs from the Database (`availableAml` = file names in EFI/OC/ACPI) using the
// tables; fills plan->acpi / acpiManaged and appends notes.
void planAcpi(const QJsonObject& report, const AcpiInfo& acpi, Plan* plan,
              const QStringList& availableAml);

// Applies the user's overrides to an automatic plan.
void overrideSmbios(Plan* p, const QString& model);
void overrideKexts(Plan* p, const QStringList& kexts);

// Loads and validates a Hardware Sniffer "Report.json". Returns false and
// fills `errors` if it is not usable.
bool loadReport(const QString& path, QJsonObject* report, QStringList* errors);
QStringList validateReport(const QJsonObject& report);

Compatibility checkCompatibility(const QJsonObject& report);
Plan makePlan(const QJsonObject& report, const Compatibility& compat,
              const QString& targetDarwinMax);

// Applies a plan to a parsed template config (kernel kexts, boot-args, SMBIOS).
// `availableKexts` are the kext bundle names present in the Database.
// disableKexts: kexts the user removed from the default list; forced off.
QVariantMap applyPlan(QVariantMap config, const Plan& plan,
                      const QStringList& availableKexts,
                      QStringList* missingKexts,
                      const QStringList& disableKexts = QStringList(),
                      const QString& kextDir = QString());

// Drops every disabled entry from ACPI > Add and Kernel > Add, so the generated
// config lists (and the EFI folder copies) only what the build actually uses.
// Returns how many entries were removed. Unrelated sections are untouched.
int pruneUnused(QVariantMap* config);

// macOS 26 Tahoe (Darwin 25) removed AppleHDA, so AppleALC alone no longer gives
// audio. OpCore Simplify asks how to restore it; this is that choice.
// True when the report has a supported codec and the target is Darwin 25 or newer.
bool audioNeedsTahoeChoice(const QJsonObject& report, const QString& targetDarwin);

// useOclp=false: AppleALC + SimpleHDA kext (no root patches; the planner default).
// useOclp=true : AppleALC only; AppleHDA is restored with OpenCore Legacy Patcher
//                root patches, which also needs AMFIPass, -amfipassbeta and
//                SecureBootModel = Disabled.
void overrideAudioKext(Plan* p, bool useOclp);

// One selectable GPU combination (OpCore Simplify "GPU combination").
struct GpuCombo {
  QStringList names;  // GPU names as keys of report["GPU"]
  Range range;        // macOS range supported by all of them together
};

// Valid GPU combinations, as OpCore Simplify offers them when the report has
// several GPUs (APU / Navi 22 / the rest are kept apart to avoid kext conflicts).
// Sorted by size then name; empty when the report has fewer than 2 GPUs.
QList<GpuCombo> gpuCombinations(const QJsonObject& report, const Compatibility& c);

// Copy of the report that keeps only the named GPUs.
QJsonObject withGpus(const QJsonObject& report, const QStringList& keep);

// Adds disable-gpu to DeviceProperties for every GPU in `full` that is missing
// from `active`. Returns how many were disabled.
int disableGpus(QVariantMap* config, const QJsonObject& full, const QJsonObject& active);

// macOS releases (name, darwin major) usable within a compat range.
QList<QPair<QString, int>> macosChoices(const Compatibility& compat);
QString macosName(int darwinMajor);

// ---- user customization (SMBIOS / kexts), mirrors OpCore-Simplify menus ----
struct SmbiosModel {
  QString name, cpu, gpu;
  QString minV, maxV;
  bool supported = false;  // supports the target Darwin version
  bool platformMatch = false;  // laptop <-> MacBook*, desktop <-> others
};
// All Mac models, flagged against the target Darwin version and platform.
QList<SmbiosModel> smbiosModels(const QJsonObject& report, const QString& targetDarwin);

struct KextInfo {
  QString name, category, description;
  QString minV, maxV;
  bool required = false;
  bool compatible = false;   // inside [min,max] for the target
  bool inDatabase = false;   // the Database ships the .kext
  QString conflictGroup;     // non-empty: only one of the group may be on
  QStringList requires_;
};
// Full catalog flagged for the target; `database` = kext bundle names shipped.
QList<KextInfo> kextCatalog(const QString& targetDarwin, const QStringList& database);
// Drops kexts that conflict (same group) or lack a compatible dependency.
QStringList resolveKexts(const QStringList& wanted, const QString& targetDarwin);

// Raw catalog record for a kext (includes "gh" / "url" download sources).
QJsonObject kextRecord(const QString& name);

// Darwin "x.y.z" helpers.
int darwinMajor(const QString& v);
bool darwinLess(const QString& a, const QString& b);

}  // namespace EfiBuilder

#endif  // EFIBUILDER_H
